demo = {(0,0),(0,11),(1,4),(2,7),(3,1),(3,13),(4,10),(5,6),(5,15)}
recolored = {(0,0),(0,11),(1,4),(2,7),(5,15)}
test = {(1,7),(1,13),(2,2),(2,7),(2,13),(3,2),(4,4),(4,11),(5,0),(5,4),(5,8),(5,11),(6,0),(6,8)}
